import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"41、【损】 兑下艮上","description":"周易尚氏学 - 41、【损】 兑下艮上","frontmatter":{"title":"41、【损】 兑下艮上","description":"周易尚氏学 - 41、【损】 兑下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/046.md","filePath":"zh/classics/shangshi/046.md"}'),h={name:"zh/classics/shangshi/046.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_41、【损】-兑下艮上" tabindex="-1">41、【损】 兑下艮上 <a class="header-anchor" href="#_41、【损】-兑下艮上" aria-label="Permalink to “41、【损】 兑下艮上”">​</a></h1><p>贞我悔彼。以我之阳。益彼之上。故曰损。归藏作员。朱彝尊谓即损卦。然归藏以益为诚。则此未必取义于损。按员古作云。商颂景员维何。笺员古文作云。以此例之。归藏必原作云也。说文。云山川气也。象回转形。后人加雨作云。是云即云字。卦上艮下兑。说卦由泽通气。气即云。中互坤。坤正为云。卦二至上正反震。震为出。云出泽中。至上而反。正回转之形。与说文合。与卦象合。六爻皆有应。故曰有孚。二阳遇阴。乾元通。故曰元吉。可贞。言二不宜升毛再损也。利有攸往谓上也。上九下乘重阴。颐曰利涉大川。利涉即利往也。尔雅释诂。曷止也。而曷与曷（左心）通。诗大雅。汽可小曷（左心）。传曷（左心）息也。息止义同。故集韵云。曷（左心）或作曷也。而曷（左心）与甜通。诗甘棠篇。召伯所矩。释文。慈本又作曷（左心）。曷之用言憩息之时也。上卦艮。故云憩。震为簋。坤数二。故曰二簋。况为亨。亨飨通。左传成十二年享以训恭俭。释文享本亦作飨。又庄四年止而飨之。周语。大臣飨其禄。注皆训飨为食。易之用二簋可用享。言当休暇之时。可以二簋为亨。二篮虽俭。然处损时。亦可也。清儒承荀氏旧说。见言簋即以为祭宗庙。侈陈礼制。岂知仪礼公食大夫扎。宰夫启簋。诗秦风于我乎食四簋。凡宴享皆用簋。非必祭宗庙始用也。且于易义之谓何矣。崔憬以曷为何。荀爽等只说二簋可用享。不及曷义。于是清儒如惠栋焦循张惠言孙星衍等。亦不释曷义。只一姚配中袭崔憬说。疑非也。</p><p>彖曰。损。损下益上。其道上行。损而有孚。元吉。无咎。可贞。利有攸往。曷之用。二簋可用享。二簋应有时。损刚益柔有时。损益盈虚。与时偕行。</p><p>贞我悔彼。内与外。上与下。其亲疏迥不相同。故夫以内阳益外。则我损矣。上下即内外也。泰三往上。故曰其道上行。震为应。二至四震。乃上卦震覆。若反声相应者。故曰二簋应。与中孚之鹤鸣子和理同也。二簋应有时。言时当曷（左心）息。用二簋享。正与时应也。泰极还否。损者泰之终。否之始。损刚益柔有时者。按卦气。损为七月卦。时已当否。阳日减。阴日增。正损刚益柔之时。不可不预知也。时当益则益。时当损则损。益则盈。损则虚。乾盈坤虚。应时而行。所谓穷则变。变则通也。</p><p>象曰。山下有泽。损。君子以惩忿窒欲。</p><p>震为决躁。为武人。故为忿。乃上卦震覆为艮。艮止故曰惩忿。二至上正覆震。震为口有争食象。坤闭故曰窒欲。学易之君子。因以取法焉。</p><p>初九。已事这往。无咎。酌损之。</p><p>已虞作祀。晁氏云。巳古文祀宇。按金文沈子它敦铭。用飨响已公。已公即祀公。初应在四。四震为祭祀。兑为晌。遗速也。祀事遗往者。言宜往应四也。当位故无咎。所应为阴。故曰酌损。</p><h3 id="象曰。已事遥往。尚合志也。" tabindex="-1">象曰。已事遥往。尚合志也。 <a class="header-anchor" href="#象曰。已事遥往。尚合志也。" aria-label="Permalink to “象曰。已事遥往。尚合志也。”">​</a></h3><p>尚上同。上谓四。初四婚媾。故曰合志。四坤为志。其用卦变以坎为志者。非也。</p><p>九二。利贞。征凶。弗损。益之。</p><p>三已损矣。二不宜再损。故利于贞定也。震为征。二阳临重阴。更利于征。然二往五则下愈损。故征凶也。弗损者。即贞于二不动。不再损下也。弗损即益二矣。故曰益之。夫贞我侮彼。泰三阳三阴。而阳全在我。此所以为泰也。损我一阳以益外。已非善征。若损之不已。则成否矣。否天地闭。贤人隐。故于二爻着以为戒。曰利贞。曰征凶。旧解惟王弼能识二之不宜往五。谓刚全上则剥道成。若虞翻则谓二不征之五则凶。故反经为说。岂知二阳得五阴为应。利往诚为常例。独损二因其利往。再损内也。故因以为戒。乃后世如惠栋张惠言等。多祖述其说。独姚配中识虞义之反经。乃又以利贞为之正。二之正成阴。阴与阴不相应。故征凶。仍以卦变为穿凿。然则不独易象失传。易理之失传更甚也。</p><h3 id="象曰。九二利贞。中以为志也。" tabindex="-1">象曰。九二利贞。中以为志也。 <a class="header-anchor" href="#象曰。九二利贞。中以为志也。" aria-label="Permalink to “象曰。九二利贞。中以为志也。”">​</a></h3><p>中谓二。言志贞于二。不前进也。故曰中以为志。旧解无不误者。</p><p>六三。三人行则损一人。一人行则得其友。</p><p>乾为人。泰三阳原为三人。今成兑。损一人矣。损三以益上。上乘重阴。阳以阴为友。故曰一人行则得其友。友谓四五。旧解以下应兑为友。故于三则疑之故。无有通者。</p><h3 id="象曰。一人行三则疑也。" tabindex="-1">象曰。一人行三则疑也。 <a class="header-anchor" href="#象曰。一人行三则疑也。" aria-label="Permalink to “象曰。一人行三则疑也。”">​</a></h3><p>三阳上行则成否。否上九为四五所阻格。所谓敌也。敌则相疑相忌。而不相友矣。释得友之故也。易于阴阳相遇为朋友之故。言之可谓明白矣。乃自荀虞以来。以兑二阳房二阴为朋友。相承至今。岂知阳遇阳阴遇阴。艮谓之敌应。中孚谓之得敌哉。</p><p>六四。损其疾。使遄有喜。无咎。</p><p>坤为疾。四得阳应。故曰损其疾。遄往也。坤为忧。乾为喜。使遗有喜者。言往得阳应而喜也。坤疾象失传。旧解故多不当。</p><h3 id="象曰。损其疾。亦可喜也。疾损故可喜。" tabindex="-1">象曰。损其疾。亦可喜也。疾损故可喜。 <a class="header-anchor" href="#象曰。损其疾。亦可喜也。疾损故可喜。" aria-label="Permalink to “象曰。损其疾。亦可喜也。疾损故可喜。”">​</a></h3><p>六五。或益之十朋之龟。弗克违。元吉。</p><p>艮为龟。汉书食货志注。苏林曰。两贝为朋。朋值二百一十六。元龟十朋。艮为朋友。坤数十。故曰十朋之龟。言阳在上五得承之。若大宝之益也。阴顺阳。故曰弗克违。五卦位最尊尊。故曰元吉。艮龟象失传。侯果谓内柔外刚龟之象。岂知艮即为龟。</p><h3 id="象曰。六五元吉。自上佑也" tabindex="-1">象曰。六五元吉。自上佑也 <a class="header-anchor" href="#象曰。六五元吉。自上佑也" aria-label="Permalink to “象曰。六五元吉。自上佑也”">​</a></h3><p>上为阳。五承之。故曰自上佑。估福也。释文或作佑。无言汉人作右者。惠栋擅改之。后学盲从之。于是集解之文遂乱矣。不可不知。又自虞翻以来。皆以二益五为说。清孺皆宗之。不椎与象传背。且与经背。经于九二言征凶。言利贞。言弗损。则二固不往五。况象传明言自上信。则十朋之龟指上也。弗克违。言五承上也。则以二益五为说者。其误益明矣。</p><p>上九。弗损益之。无咎。贞吉。利有攸往。得巨无家。</p><p>上之三则上损矣。不动则益上。故曰弗损益之。贞吉者卜问吉也。上乘重阴，故利有攸往。与颐上九同。坤为臣。上据坤。是得臣为助也。三者上九之家。上既得臣为助。即不返三。故曰得臣无家。盲公而忘私也。</p><h3 id="象曰。弗损益之。大得志也" tabindex="-1">象曰。弗损益之。大得志也 <a class="header-anchor" href="#象曰。弗损益之。大得志也" aria-label="Permalink to “象曰。弗损益之。大得志也”">​</a></h3><p>坤为志。上据坤。阳乘阴。故曰大得志。旧解皆以上返三为说。非。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
